/**
 * Build both halves of dsh-hunk into lib/.
 *
 * - `lib/index.js` — the host half, plain ESM for node (only `node:` imports).
 * - `lib/client.js` — the browser half, in the exact shape the DSH client
 *   module system expects: a lazy factory registered under the package name
 *   (`window.__ModuleLoader__.load({ id, factory })`). react and
 *   react/jsx-runtime stay external because the shell's module table owns
 *   those instances; everything else is bundled.
 *
 * Declarations are emitted by `tsc -p tsconfig.build.json` (see package.json).
 */
import { build } from 'esbuild'
import { mkdir, readFile, rm, writeFile } from 'node:fs/promises'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = dirname(fileURLToPath(import.meta.url))
const outDir = resolve(root, 'lib')
const manifest = JSON.parse(await readFile(resolve(root, 'package.json'), 'utf8'))

const shared = {
  bundle: true,
  sourcemap: true,
  logLevel: 'info',
  legalComments: 'none',
}

/** Wrap one CJS bundle body in the module-loader registration. */
function registerBundle(id, body, mapComment) {
  const indented = body
    .split('\n')
    .map(line => (line === '' ? '' : `\t\t${line}`))
    .join('\n')
  return [
    '// Generated by build.mjs — do not edit; edit src/ and rebuild.',
    'window.__ModuleLoader__.load({',
    `\tid: ${JSON.stringify(id)},`,
    '\tfactory(require) {',
    '\t\tvar module = { exports: {} };',
    '\t\tvar exports = module.exports;',
    indented,
    '\t\treturn module.exports;',
    '\t},',
    '});',
    mapComment,
    '',
  ].join('\n')
}

await rm(outDir, { recursive: true, force: true })
await mkdir(outDir, { recursive: true })

await build({
  ...shared,
  entryPoints: [resolve(root, 'src/index.ts')],
  outfile: resolve(outDir, 'index.js'),
  platform: 'node',
  format: 'esm',
  target: 'node20',
})

const clientResult = await build({
  ...shared,
  entryPoints: [resolve(root, 'src/client/index.tsx')],
  outfile: resolve(outDir, 'client.js'),
  platform: 'browser',
  format: 'cjs',
  target: 'es2020',
  jsx: 'automatic',
  jsxDev: false,
  define: { 'process.env.NODE_ENV': '"production"' },
  external: ['react', 'react/jsx-runtime', 'react-dom', 'react-dom/client'],
  write: false,
})

const clientJs = clientResult.outputFiles.find(file => file.path.endsWith('.js'))
const clientMap = clientResult.outputFiles.find(file => file.path.endsWith('.map'))
if (clientJs === undefined) throw new Error('esbuild produced no client bundle')

// The sourceMappingURL comment belongs after the registration, not inside the
// factory body.
const mapComment = '//# sourceMappingURL=client.js.map'
const body = clientJs.text.replace(/\/\/# sourceMappingURL=.*\s*$/, '').trimEnd()
await writeFile(resolve(outDir, 'client.js'), registerBundle(manifest.name, body, mapComment), 'utf8')
if (clientMap !== undefined) await writeFile(resolve(outDir, 'client.js.map'), clientMap.text, 'utf8')

console.log(`[dsh-hunk] built lib/index.js and lib/client.js (client id: ${manifest.name})`)
